-- Processing RPCs and immutable document storage hardening
alter table public.documents add column if not exists content_hash text;
alter table public.documents add column if not exists generated_at timestamptz;
alter table public.documents add column if not exists signed_at timestamptz;
alter table public.documents add column if not exists immutable boolean not null default false;
insert into storage.buckets(id,name,public) values('documents','documents',false) on conflict(id) do nothing;
create policy "document owner storage read" on storage.objects for select to authenticated using(bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "document owner storage insert" on storage.objects for insert to authenticated with check(bucket_id='documents' and (storage.foldername(name))[1]=(select auth.uid())::text);
create or replace function public.admin_record_market_price(p_asset_id uuid,p_price_date date,p_close_price numeric,p_currency text,p_source text,p_source_reference text default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not public.is_staff() then raise exception 'staff access required';end if;insert into public.market_prices(asset_id,price_date,close_price,currency,source,source_reference)values(p_asset_id,p_price_date,p_close_price,p_currency,p_source,p_source_reference)on conflict(asset_id,price_date,source)do update set close_price=excluded.close_price,currency=excluded.currency,source_reference=excluded.source_reference returning id into v_id;return v_id;end$$;
create or replace function public.admin_record_performance(p_user_id uuid,p_portfolio_version_id uuid,p_as_of_date date,p_beginning_value numeric,p_ending_value numeric,p_net_cash_flow numeric,p_twr numeric,p_mwr numeric,p_benchmark_return numeric default null,p_alpha numeric default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not public.is_staff() then raise exception 'staff access required';end if;insert into public.performance_snapshots(user_id,portfolio_version_id,as_of_date,beginning_value,ending_value,net_cash_flow,twr,mwr,benchmark_return,alpha)values(p_user_id,p_portfolio_version_id,p_as_of_date,p_beginning_value,p_ending_value,p_net_cash_flow,p_twr,p_mwr,p_benchmark_return,p_alpha)on conflict(user_id,portfolio_version_id,as_of_date)do update set ending_value=excluded.ending_value,net_cash_flow=excluded.net_cash_flow,twr=excluded.twr,mwr=excluded.mwr,benchmark_return=excluded.benchmark_return,alpha=excluded.alpha returning id into v_id;return v_id;end$$;
create or replace function public.admin_create_compliance_case(p_case_type text,p_user_id uuid,p_severity text,p_title text,p_description text,p_due_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not public.is_staff() then raise exception 'staff access required';end if;insert into public.compliance_cases(case_type,user_id,severity,title,description,due_at,assigned_to)values(p_case_type,p_user_id,p_severity,p_title,p_description,p_due_at,auth.uid())returning id into v_id;return v_id;end$$;
create or replace function public.admin_set_rebalance_status(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_staff() then raise exception 'staff access required';end if;update public.rebalance_orders set status=p_status,approved_by=case when p_status='approved' then auth.uid() else approved_by end,executed_at=case when p_status='executed' then now() else executed_at end where id=p_id;if not found then raise exception 'rebalance order not found';end if;end$$;
create or replace function public.admin_resolve_reconciliation_item(p_id uuid,p_resolution text) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_staff() then raise exception 'staff access required';end if;update public.reconciliation_items set status='resolved',resolution=p_resolution,resolved_by=auth.uid(),resolved_at=now() where id=p_id;if not found then raise exception 'reconciliation item not found';end if;end$$;
create or replace function public.admin_process_corporate_action(p_id uuid) returns void language plpgsql security definer set search_path=public as $$declare a public.corporate_actions%rowtype;begin if not public.is_staff() then raise exception 'staff access required';end if;select * into a from public.corporate_actions where id=p_id for update;if not found then raise exception 'corporate action not found';end if;if a.status not in('approved','scheduled') then raise exception 'corporate action must be approved or scheduled';end if;update public.corporate_actions set status='processed',updated_at=now() where id=p_id;insert into public.governance_events(event_type,entity_type,entity_id,actor_id,details)values('corporate_action_processed','corporate_action',a.id,auth.uid(),jsonb_build_object('action_type',a.action_type,'asset_id',a.asset_id));end$$;
revoke execute on function public.admin_record_market_price(uuid,date,numeric,text,text,text) from public,anon; grant execute on function public.admin_record_market_price(uuid,date,numeric,text,text,text) to authenticated;
revoke execute on function public.admin_record_performance(uuid,uuid,date,numeric,numeric,numeric,numeric,numeric,numeric,numeric) from public,anon; grant execute on function public.admin_record_performance(uuid,uuid,date,numeric,numeric,numeric,numeric,numeric,numeric,numeric) to authenticated;
revoke execute on function public.admin_create_compliance_case(text,uuid,text,text,text,timestamptz) from public,anon; grant execute on function public.admin_create_compliance_case(text,uuid,text,text,text,timestamptz) to authenticated;
revoke execute on function public.admin_set_rebalance_status(uuid,text) from public,anon; grant execute on function public.admin_set_rebalance_status(uuid,text) to authenticated;
revoke execute on function public.admin_resolve_reconciliation_item(uuid,text) from public,anon; grant execute on function public.admin_resolve_reconciliation_item(uuid,text) to authenticated;
revoke execute on function public.admin_process_corporate_action(uuid) from public,anon; grant execute on function public.admin_process_corporate_action(uuid) to authenticated;
